{-# LANGUAGE OverloadedStrings #-}
{-# LANGUAGE LambdaCase #-}
{-# LANGUAGE RankNTypes #-}

-- | The machinery that parsers generated by peg-hs are built on.
--
-- __This module exists for generated modules. It is not meant to be used
-- directly.__ Application code should import "Peg.Runtime", which
-- re-exports the user-facing part (positions and errors), and
-- "Peg.Runtime.Syntax" for syntax trees. Generated modules import this
-- module qualified as @PegRt@ and call the functions below; the names and
-- types here are the contract between the generator (the @peg-codegen@
-- package) and the runtime. Because code generated by an earlier peg-hs
-- keeps calling them, the module follows the PVP like the other exposed
-- modules: any change that removes or changes something here is a major
-- version change of @peg-runtime@.
--
-- A generated entry point is a thin wrapper around 'runParser' (or
-- 'runParserRecover' and 'runSyntaxRecover' for the recovering entry
-- points). Each rule becomes a parser of type t'P' wrapped in 'memo',
-- 'memoLR', 'memoArg' or 'nomemo', with a memo table in a generated store
-- created by 'newTable' or 'newArgTable'. The rule bodies are built from
-- the terminals ('lit', 'cls', 'anyChar') and combinators ('choice',
-- 'many', 'andP', 'notP', 'labeled', ...). In a grammar with @%syntax@ the
-- parsers also return the children of the syntax tree ('node', 'token',
-- 'label' and the functions ending in @S@).
--
-- Every parse runs in 'ST'. Results of rule invocations are memoised in
-- sparse tables keyed by byte offset, so non-left-recursive grammars run in
-- time linear in the input. Rules that take part in left recursion are
-- evaluated with the bounded left recursion semantics of Medeiros,
-- Mascarenhas and Ierusalimschy (2014): the memo entry is seeded with a
-- failure and the rule body is re-evaluated while the match keeps growing.
module Peg.Runtime.Internal
  ( -- * Positions
    Pos (..)
  , Span (..)
    -- * Errors
  , Expected (..)
  , ParseError (..)
  , renderParseError
    -- * Running a parser
  , Config (..)
  , defaultConfig
  , Stats (..)
  , runParser
    -- * The parser type
  , P
  , ST
  , Text
    -- * Memo tables
  , Table
  , ArgTable
  , newTable
  , newArgTable
  , memo
  , memoArg
  , memoLR
  , nomemo
    -- * Terminals
  , lit
  , cls
  , anyChar
    -- * Combinators
  , choice
  , many
  , many1
  , skipMany
  , skipMany1
  , optional
  , skipOptional
  , andP
  , notP
  , capture
  , predicate
  , withCol
    -- * Context
  , getOffset
  , spanFrom
  , askStore
    -- * Syntax trees (ADR 0019)
  , SyntaxKind (..)
  , Child
  , SyntaxNode
  , SyntaxToken
  , SyntaxElement
  , syntaxRoot
  , syntaxKind
  , labeledElements
  , labeledNode
  , labeledToken
  , labeledNodes
  , labeledTokens
  , node
  , token
  , plain
  , label
  , manyS
  , many1S
  , optionalS
  , captureS
  , labelText
  , touch
    -- * Labelled failures and recovery (ADR 0021)
  , SyntaxError (..)
  , runParserRecover
  , runSyntaxRecover
  , labeled
  , labeledS
  , voidP
  , voidS
  ) where

import Control.Monad (ap, when)
import Control.Monad.ST (ST, runST)
import Data.Array.Unboxed ((!))
import Data.IntMap.Strict (IntMap)
import Data.IntSet (IntSet)
import qualified Data.IntSet as IS
import Data.List (partition, sortOn)
import qualified Data.IntMap.Strict as IM
import Data.Map.Strict (Map)
import qualified Data.Map.Strict as M
import Data.STRef (STRef, modifySTRef', newSTRef, readSTRef, writeSTRef)
import Data.Set (Set)
import qualified Data.Set as S
import Data.Text (Text)
import qualified Data.Text as T
import qualified Data.Text.Unsafe as TU
import Peg.Runtime.Position
import Peg.Runtime.Syntax

-- | A range of the input, from 'spanStart' (inclusive) to 'spanEnd'
-- (exclusive).
data Span = Span
  { spanStart :: !Pos
  , spanEnd :: !Pos
  }
  deriving (Eq, Ord, Show)

-- | Something the parser expected to find at the position of a failure.
--
-- The constructor order defines the order in which expectations are listed.
data Expected
  = -- | A literal, as written in the grammar (including its quotes).
    ExpectedLiteral !Text
  | -- | A character class, as written in the grammar.
    ExpectedClass !Text
  | -- | Any single character.
    ExpectedAny
  | -- | The end of the input.
    ExpectedEnd
  deriving (Eq, Ord, Show)

-- | Why a parse failed. 'renderParseError' turns it into a message.
--
-- When several alternatives fail, the error is the one that got farthest:
-- 'parseErrorPos' is the farthest position any terminal was tried at, and
-- 'parseErrorExpected' collects every terminal that failed there. Failures
-- inside negative lookahead and semantic predicates are not reported.
data ParseError = ParseError
  { parseErrorPos :: !Pos
  -- ^ The farthest position the parser reached.
  , parseErrorExpected :: !(Set Expected)
  -- ^ The terminals that were tried and failed at that position.
  , parseErrorLabel :: !(Maybe Text)
  -- ^ The label of the labelled failure that stopped the parse, if any
  -- (ADR 0021).
  }
  deriving (Eq, Show)

-- | A syntax error that a recovering parse recovered from (ADR 0021).
--
-- The recovering entry points of a generated module (@parseRecover@,
-- @parseSyntaxRecover@) return these sorted by position:
--
-- @
-- case parseRecover src of
--   (value, errs) -> do
--     forM_ errs $ \\e -> do
--       let p = syntaxErrorPos e
--       putStrLn (show (posLine p) ++ \":\" ++ show (posColumn p) ++ \": \" ++ maybe \"unexpected input\" T.unpack (syntaxErrorLabel e))
--     print value  -- Nothing only if the start rule could not be recovered
-- @
data SyntaxError = SyntaxError
  { syntaxErrorLabel :: !(Maybe Text)
  -- ^ The label that was thrown. 'Nothing' for input left over after the
  -- start rule and for a start rule that could not be recovered.
  , syntaxErrorRange :: !(Int, Int)
  -- ^ The byte range the recovery skipped. It is empty when the recovery
  -- consumed nothing.
  , syntaxErrorPos :: Pos
  -- ^ The position of the start of the range. Computed when used: the
  -- column takes time proportional to the length of the line.
  , syntaxErrorExpected :: !(Set Expected)
  -- ^ What the parser expected at the farthest failure of the labelled
  -- expression.
  }
  deriving (Eq, Show)

-- | Render an error as @line:column: expected A, B or C@.
--
-- The expectations are listed in the order of 'Expected': literals and
-- classes as written in the grammar, then @any character@, then
-- @end of input@. With no expectation the message is @parse error@. The
-- label of 'parseErrorLabel' is not included; map it to a message of your
-- own if the grammar uses labels.
--
-- @
-- case parse \"1 +\" of
--   Left err -> TIO.putStrLn (renderParseError err)  -- 1:4: expected \'(\' or [0-9]
--   Right v -> print v
-- @
renderParseError :: ParseError -> Text
renderParseError e =
  T.concat
    [ T.pack (show (posLine p))
    , ":"
    , T.pack (show (posColumn p))
    , ": "
    , case map renderExpected (S.toAscList (parseErrorExpected e)) of
        [] -> "parse error"
        xs -> "expected " <> joinOr xs
    ]
  where
    p = parseErrorPos e
    joinOr [x] = x
    joinOr xs = T.intercalate ", " (init xs) <> " or " <> last xs

renderExpected :: Expected -> Text
renderExpected = \case
  ExpectedLiteral t -> t
  ExpectedClass t -> t
  ExpectedAny -> "any character"
  ExpectedEnd -> "end of input"

-- | Options for a parse. Generated parsers use 'defaultConfig', with
-- 'cfgTabstop' set by @%tabstop@; the other settings exist for testing the
-- runtime and the generator (the @peg'parseWith@ entry point that
-- @peg-hs gen --debug-entry@ adds).
data Config = Config
  { cfgMemo :: !Bool
  -- ^ Memoise rules that are not left-recursive. Left-recursive rules are
  -- always memoised, since their semantics depends on the memo table.
  , cfgDiscard :: !Bool
  -- ^ Discard memo entries that depend on the seed of a left recursion
  -- growth loop at the end of each of its iterations. Turning this off is
  -- only useful for tests.
  , cfgDiscardAll :: !Bool
  -- ^ Discard every memo entry written during an iteration instead, whether
  -- it depends on the seed or not (ADR 0013). Only useful for comparing the
  -- two in tests.
  , cfgCount :: !Bool
  -- ^ Count rule body evaluations into t'Stats'.
  , cfgTabstop :: !Int
  -- ^ Tab stop used by the column passed to predicates and rule arguments
  -- (@_col@). 0 means a tab counts as a single column.
  , cfgRecover :: !Bool
  -- ^ Recover from labelled failures with the recovery rules (ADR 0021).
  -- 'runParserRecover' and 'runSyntaxRecover' turn it on and 'runParser'
  -- turns it off, so setting it has no effect.
  }
  deriving (Eq, Show)

-- | Memoisation and discarding on, counting off, no tab stop.
defaultConfig :: Config
defaultConfig = Config {cfgMemo = True, cfgDiscard = True, cfgDiscardAll = False, cfgCount = False, cfgTabstop = 0, cfgRecover = False}

-- | Counters collected when 'cfgCount' is on.
data Stats = Stats
  { statsEvaluations :: !(Map (Text, Int) Int)
  -- ^ How many times the body of each rule was evaluated at each offset.
  , statsMemoEntries :: !Int
  -- ^ The number of memo entries alive at the end of the parse.
  , statsEntriesByRule :: !(Map Text Int)
  -- ^ The memo entries alive at the end of the parse, by rule.
  }
  deriving (Eq, Show)

emptyStats :: Stats
emptyStats = Stats M.empty 0 M.empty

data Failure
  = NoFailure
  | Failure !Int !(Set Expected)
  deriving (Eq, Show)

mergeFailure :: Failure -> Failure -> Failure
mergeFailure NoFailure f = f
mergeFailure f NoFailure = f
mergeFailure a@(Failure i xs) b@(Failure j ys)
  | i > j = a
  | i < j = b
  | otherwise = Failure i (S.union xs ys)

-- | The result of running a parser at an offset.
data Res a
  = Ok !Int a
  | Fail
  | -- | A labelled failure: the position where the labelled expression was
    -- tried and the label (ADR 0021).
    Throw !Int !Text

-- The syntax errors recorded so far: how many, and the errors, newest first.
-- The count makes saving and comparing the log constant time.
data ErrLog = ErrLog !Int [SyntaxError]

-- The errors recorded by one evaluation: the first @n@ elements of a log.
-- The list is shared with the log, so storing it in a memo entry copies
-- nothing.
data ErrSlice = ErrSlice !Int [SyntaxError]

noErrors :: ErrSlice
noErrors = ErrSlice 0 []

-- Re-type a result that is not a success.
failed :: Res a -> Res b
failed (Throw i l) = Throw i l
failed _ = Fail

data Ctx r s = Ctx
  { ctxInput :: !Text
  , ctxLen :: !Int
  , ctxStore :: r
  , ctxFail :: !(STRef s Failure)
  , ctxErrors :: !(STRef s ErrLog)
  , -- | The growth loops whose seeds the evaluation in progress has read,
    -- numbered from 1 for the outermost loop running (ADR 0024).
    ctxDeps :: !(STRef s IntSet)
  , -- | The number of growth loops running.
    ctxDepth :: !(STRef s Int)
  , -- | For each iteration of the growth loops running, innermost first, the
    -- memo entries written that may have to be discarded: their dependencies
    -- and how to remove them.
    ctxLogs :: !(STRef s [[(IntSet, ST s ())]])
  , ctxStats :: !(STRef s Stats)
  , ctxConfig :: !Config
  , ctxLines :: LineIndex
  }

-- | A parser over a generated store @r@ in the state thread @s@.
newtype P r s a = P {unP :: Ctx r s -> Int -> ST s (Res a)}

instance Functor (P r s) where
  fmap f (P p) =
    P $ \c i ->
      p c i >>= \case
        Ok j x -> pure (Ok j (f x))
        bad -> pure (failed bad)

instance Applicative (P r s) where
  pure x = P $ \_ i -> pure (Ok i x)
  (<*>) = ap

instance Monad (P r s) where
  P p >>= k =
    P $ \c i ->
      p c i >>= \case
        Ok j x -> unP (k x) c j
        bad -> pure (failed bad)

-- | Run the start rule over the whole input. The arguments are the
-- configuration, the action that creates the generated store of memo
-- tables, the start rule and the input.
--
-- The parse succeeds only if the start rule consumes the entire input;
-- otherwise 'ExpectedEnd' is expected where the match ended. A label
-- thrown by 'labeled' stops the parse and is reported in
-- 'parseErrorLabel'; recovery is off, whatever 'cfgRecover' says.
--
-- A generated entry point calls it like this (names simplified):
--
-- @
-- parse :: Text -> Either ParseError Expr
-- parse input = fst (runParser config newStore rule_Expr input)
-- @
runParser
  :: Config
  -> (forall s. ST s (store s))
  -> (forall s. P (store s) s a)
  -> Text
  -> (Either ParseError a, Stats)
runParser cfg mkStore start input = runST $ do
  ctx <- newCtx cfg {cfgRecover = False} mkStore input
  r <- unP start ctx 0
  res <- case r of
    Ok j x | j == ctxLen ctx -> pure (Right x)
    Ok j _ -> do
      mergeFail ctx (Failure j (S.singleton ExpectedEnd))
      Left <$> currentError ctx Nothing
    Throw _ l -> Left <$> currentError ctx (Just l)
    Fail -> Left <$> currentError ctx Nothing
  s <- readSTRef (ctxStats ctx)
  pure (res, s)

newCtx :: Config -> ST s (store s) -> Text -> ST s (Ctx (store s) s)
newCtx cfg mkStore input = do
  st <- mkStore
  fref <- newSTRef NoFailure
  errs <- newSTRef (ErrLog 0 [])
  logs <- newSTRef []
  deps <- newSTRef IS.empty
  depth <- newSTRef 0
  stats <- newSTRef emptyStats
  pure
    Ctx
      { ctxInput = input
      , ctxLen = TU.lengthWord8 input
      , ctxStore = st
      , ctxFail = fref
      , ctxErrors = errs
      , ctxDeps = deps
      , ctxDepth = depth
      , ctxLogs = logs
      , ctxStats = stats
      , ctxConfig = cfg
      , ctxLines = lineIndex input
      }

currentError :: Ctx r s -> Maybe Text -> ST s ParseError
currentError ctx failLabel =
  readSTRef (ctxFail ctx) >>= \case
    NoFailure -> pure (ParseError (posAt ctx 0) S.empty failLabel)
    Failure i xs -> pure (ParseError (posAt ctx i) xs failLabel)

-- | Run the start rule over the whole input, recovering from labelled
-- failures (ADR 0021). The value is 'Nothing' only if the start rule could
-- not be recovered. Errors are sorted by position. Input left over after
-- the start rule is reported as a t'SyntaxError' without a label, and so
-- is a start rule that could not be recovered.
runParserRecover
  :: Config
  -> (forall s. ST s (store s))
  -> (forall s. P (store s) s a)
  -> Text
  -> (Maybe a, [SyntaxError], Stats)
runParserRecover cfg mkStore start input =
  let (value, errs, st) = recoverCore cfg mkStore start input
   in (fmap snd value, errs, st)

-- | 'runParserRecover' for a grammar with @%syntax@. Always returns a tree:
-- input left over after the start rule, or the whole input if the start
-- rule could not be recovered, becomes an error node (of kind
-- 'Peg.Runtime.Syntax.errorKind'). The t'SyntaxKind' is the kind of the
-- root node, used when the children do not form a single node that covers
-- the input (see 'syntaxRoot').
runSyntaxRecover
  :: Config
  -> (forall s. ST s (store s))
  -> (forall s. P (store s) s (a, [Child]))
  -> SyntaxKind
  -> Text
  -> (SyntaxNode, [SyntaxError], Stats)
runSyntaxRecover cfg mkStore start k input =
  let (value, errs, st) = recoverCore cfg mkStore start input
      len = TU.lengthWord8 input
      kids = case value of
        Just (j, (_, ks))
          | j == len -> ks
          | otherwise -> ks ++ [CNode errorKind j len [] Nothing]
        Nothing -> [CNode errorKind 0 len [] Nothing]
   in (syntaxRoot input k kids, errs, st)

-- The end of the start rule's match and its value, with all errors,
-- including the one for left over input or an unrecoverable start rule.
recoverCore
  :: Config
  -> (forall s. ST s (store s))
  -> (forall s. P (store s) s a)
  -> Text
  -> (Maybe (Int, a), [SyntaxError], Stats)
recoverCore cfg mkStore start input = runST $ do
  ctx <- newCtx cfg {cfgRecover = True} mkStore input
  r <- unP start ctx 0
  errs <- (\(ErrLog _ xs) -> reverse xs) <$> readSTRef (ctxErrors ctx)
  let len = ctxLen ctx
  (value, all') <- case r of
    Ok j x | j == len -> pure (Just (j, x), errs)
    Ok j x -> do
      mergeFail ctx (Failure j (S.singleton ExpectedEnd))
      e <- wholeError ctx Nothing j
      pure (Just (j, x), errs ++ [e])
    Throw _ l -> (\e -> (Nothing, [e])) <$> wholeError ctx (Just l) 0
    Fail -> (\e -> (Nothing, [e])) <$> wholeError ctx Nothing 0
  st <- readSTRef (ctxStats ctx)
  pure (value, sortOn syntaxErrorRange all', st)
  where
    wholeError ctx failLabel from = do
      expected <-
        readSTRef (ctxFail ctx) >>= \case
          NoFailure -> pure S.empty
          Failure _ xs -> pure xs
      pure (SyntaxError failLabel (from, ctxLen ctx) (posAt ctx from) expected)

-- Positions ------------------------------------------------------------------

slice :: Text -> Int -> Int -> Text
slice t from to = TU.takeWord8 (to - from) (TU.dropWord8 from t)

posAt :: Ctx r s -> Int -> Pos
posAt ctx = posIn (ctxInput ctx) (ctxLines ctx)

-- The 0-based column of an offset, expanding tabs to 'cfgTabstop'.
colAt :: Ctx r s -> Int -> Int
colAt ctx off = T.foldl' step 0 (slice (ctxInput ctx) start off)
  where
    start = ctxLines ctx ! lineOf (ctxLines ctx) off
    ts = cfgTabstop (ctxConfig ctx)
    step col ch
      | ch == '\t' && ts > 0 = (col `div` ts + 1) * ts
      | otherwise = col + 1

-- Failures ---------------------------------------------------------------------

mergeFail :: Ctx r s -> Failure -> ST s ()
mergeFail ctx f = modifySTRef' (ctxFail ctx) (`mergeFailure` f)

failAt :: Ctx r s -> Int -> Expected -> ST s (Res a)
failAt ctx i e = Fail <$ mergeFail ctx (Failure i (S.singleton e))

-- Terminals ------------------------------------------------------------------

-- | Match a literal. The first argument is the text to match, the second the
-- literal as written in the grammar, used in error messages.
lit :: String -> String -> P r s ()
lit s orig = P $ \c i ->
  if t `T.isPrefixOf` TU.dropWord8 i (ctxInput c)
    then pure (Ok (i + n) ())
    else failAt c i expected
  where
    t = T.pack s
    n = TU.lengthWord8 t
    expected = ExpectedLiteral (T.pack orig)

-- | Match one character in any of the inclusive ranges. The second argument
-- is the class as written in the grammar.
cls :: [(Char, Char)] -> String -> P r s ()
cls ranges orig = P $ \c i ->
  if i < ctxLen c
    then
      let TU.Iter ch d = TU.iter (ctxInput c) i
       in if any (\(a, b) -> a <= ch && ch <= b) ranges
            then pure (Ok (i + d) ())
            else failAt c i expected
    else failAt c i expected
  where
    expected = ExpectedClass (T.pack orig)

-- | Match any single code point.
anyChar :: P r s ()
anyChar = P $ \c i ->
  if i < ctxLen c
    then let TU.Iter _ d = TU.iter (ctxInput c) i in pure (Ok (i + d) ())
    else failAt c i ExpectedAny

-- Combinators ----------------------------------------------------------------

-- | Ordered choice: try each alternative in turn and take the first success.
choice :: [P r s a] -> P r s a
choice ps = P $ \c i -> do
  saved <- saveErrors c
  let go [] = pure Fail
      go (p : rest) =
        unP p c i >>= \case
          r@Ok {} -> pure r
          Fail -> restoreErrors c saved >> go rest
          r -> restoreErrors c saved >> pure r
  go ps

-- Errors are only recorded in recovery mode, so only then are they saved
-- and restored when an attempt is abandoned.
saveErrors :: Ctx r s -> ST s (Maybe ErrLog)
saveErrors c
  | cfgRecover (ctxConfig c) = Just <$> readSTRef (ctxErrors c)
  | otherwise = pure Nothing

restoreErrors :: Ctx r s -> Maybe ErrLog -> ST s ()
restoreErrors c = maybe (pure ()) (writeSTRef (ctxErrors c))

-- | Zero or more repetitions, collecting the results.
many :: P r s a -> P r s [a]
many p = P $ \c i ->
  let go j acc = do
        saved <- saveErrors c
        unP p c j >>= \case
          Ok k x | k > j -> go k (x : acc)
          Throw t l -> restoreErrors c saved >> pure (Throw t l)
          _ -> restoreErrors c saved >> pure (Ok j (reverse acc))
   in go i []

-- | One or more repetitions, collecting the results.
many1 :: P r s a -> P r s [a]
many1 p = (:) <$> p <*> many p

-- | Zero or more repetitions, discarding the results.
skipMany :: P r s a -> P r s ()
skipMany p = P $ \c i ->
  let go j = do
        saved <- saveErrors c
        unP p c j >>= \case
          Ok k _ | k > j -> go k
          Throw t l -> restoreErrors c saved >> pure (Throw t l)
          _ -> restoreErrors c saved >> pure (Ok j ())
   in go i

-- | One or more repetitions, discarding the results.
skipMany1 :: P r s a -> P r s ()
skipMany1 p = p >> skipMany p

-- | An optional match.
optional :: P r s a -> P r s (Maybe a)
optional p = P $ \c i -> do
  saved <- saveErrors c
  unP p c i >>= \case
    Ok j x -> pure (Ok j (Just x))
    Fail -> restoreErrors c saved >> pure (Ok i Nothing)
    r -> restoreErrors c saved >> pure (failed r)

-- | An optional match, discarding the result.
skipOptional :: P r s a -> P r s ()
skipOptional p = () <$ optional p

-- | Positive lookahead. Consumes no input. A label thrown inside it is an
-- ordinary failure (ADR 0021).
andP :: P r s a -> P r s ()
andP p = P $ \c i -> do
  saved <- saveErrors c
  r <- unP p c i
  restoreErrors c saved
  case r of
    Ok _ _ -> pure (Ok i ())
    _ -> pure Fail

-- | Negative lookahead. Consumes no input, and failures inside it are not
-- reported.
notP :: P r s a -> P r s ()
notP p = P $ \c i -> do
  saved <- readSTRef (ctxFail c)
  savedErrors <- saveErrors c
  r <- unP p c i
  writeSTRef (ctxFail c) saved
  restoreErrors c savedErrors
  case r of
    Ok _ _ -> pure Fail
    _ -> pure (Ok i ())

-- | The input consumed by a parser.
capture :: P r s a -> P r s Text
capture p = P $ \c i ->
  unP p c i >>= \case
    Ok j _ -> pure (Ok j (slice (ctxInput c) i j))
    bad -> pure (failed bad)

-- | A semantic predicate. The function receives the current 0-based column.
-- Consumes no input, and a failure is not reported.
predicate :: (Int -> Bool) -> P r s ()
predicate f = P $ \c i ->
  pure (if f (colAt c i) then Ok i () else Fail)

-- | Pass the current 0-based column to a parser.
withCol :: (Int -> P r s a) -> P r s a
withCol f = P $ \c i -> unP (f (colAt c i)) c i

-- Context --------------------------------------------------------------------

-- | The current byte offset.
getOffset :: P r s Int
getOffset = P $ \_ i -> pure (Ok i i)

-- | The span from a byte offset to the current offset. The positions are
-- computed lazily.
spanFrom :: Int -> P r s Span
spanFrom start = P $ \c i -> pure (Ok i (Span (posAt c start) (posAt c i)))

-- | Read a field of the generated store.
askStore :: (r -> a) -> P r s a
askStore f = P $ \c i -> pure (Ok i (f (ctxStore c)))

-- Memo tables ----------------------------------------------------------------

-- A memoised result with its failure record, the syntax errors recorded
-- while evaluating it (newest first), and the growth loops whose seeds it
-- depends on.
data Entry a = Entry !(Res a) !Failure !ErrSlice !IntSet

-- | A sparse memo table for one rule, keyed by byte offset.
type Table s a = STRef s (IntMap (Entry a))

-- | A sparse memo table for a rule with arguments.
type ArgTable s k a = STRef s (IntMap (Map k (Entry a)))

-- | An empty memo table.
newTable :: ST s (Table s a)
newTable = newSTRef IM.empty

-- | An empty memo table for a rule with arguments.
newArgTable :: ST s (ArgTable s k a)
newArgTable = newSTRef IM.empty

countEval :: Ctx r s -> Text -> Int -> ST s ()
countEval c name i =
  when (cfgCount (ctxConfig c)) $
    modifySTRef' (ctxStats c) $ \st ->
      st {statsEvaluations = M.insertWith (+) (name, i) 1 (statsEvaluations st)}

bumpEntries :: Ctx r s -> Text -> Int -> ST s ()
bumpEntries c name d =
  when (cfgCount (ctxConfig c)) $
    modifySTRef' (ctxStats c) $ \st ->
      st
        { statsMemoEntries = statsMemoEntries st + d
        , statsEntriesByRule = M.insertWith (+) name d (statsEntriesByRule st)
        }

-- Evaluate a rule body with its own failure record, so that the failure can
-- be stored in the memo entry and replayed on a hit. In recovery mode the
-- syntax errors recorded by a successful evaluation are returned as well;
-- those of an unsuccessful one are discarded.
evalBody :: Ctx r s -> Text -> Int -> P r s a -> ST s (Res a, Failure, ErrSlice, IntSet)
evalBody c name i body = do
  countEval c name i
  saved <- readSTRef (ctxFail c)
  writeSTRef (ctxFail c) NoFailure
  savedDeps <- readSTRef (ctxDeps c)
  writeSTRef (ctxDeps c) IS.empty
  before <- saveErrors c
  r <- unP body c i
  f <- readSTRef (ctxFail c)
  writeSTRef (ctxFail c) (mergeFailure saved f)
  d <- readSTRef (ctxDeps c)
  writeSTRef (ctxDeps c) (IS.union savedDeps d)
  new <- case r of
    Ok {} -> newErrors c before
    _ -> noErrors <$ restoreErrors c before
  pure (r, f, new, d)

-- The errors recorded since a saved state.
newErrors :: Ctx r s -> Maybe ErrLog -> ST s ErrSlice
newErrors _ Nothing = pure noErrors
newErrors c (Just (ErrLog old _)) = do
  ErrLog now xs <- readSTRef (ctxErrors c)
  pure (ErrSlice (now - old) xs)

-- Add the errors of a slice to the log.
appendSlice :: Ctx r s -> ErrSlice -> ST s ()
appendSlice _ (ErrSlice 0 _) = pure ()
appendSlice c (ErrSlice k xs) = modifySTRef' (ctxErrors c) (\(ErrLog n ys) -> ErrLog (n + k) (take k xs ++ ys))

-- Replay a memo entry.
replay :: Ctx r s -> Entry a -> ST s (Res a)
replay c (Entry r f errs d) = do
  mergeFail c f
  when (not (IS.null d)) (modifySTRef' (ctxDeps c) (IS.union d))
  case r of
    Ok {} -> appendSlice c errs
    _ -> pure ()
  pure r

-- Record how to remove a memo entry in the innermost growth loop, if any.
-- An entry that depends on no seed is final and is not recorded, unless
-- every entry is to be discarded ('cfgDiscardAll').
logUndo :: Ctx r s -> IntSet -> ST s () -> ST s ()
logUndo c deps undo =
  when (not (IS.null deps) || cfgDiscardAll (ctxConfig c)) $
    readSTRef (ctxLogs c) >>= \case
      l : ls -> writeSTRef (ctxLogs c) (((deps, undo) : l) : ls)
      [] -> pure ()

-- End an iteration of the growth loop numbered @k@: discard the entries
-- that depend on its seed, and pass the others, which depend only on the
-- seeds of loops further out, to the iteration of the enclosing loop.
endIteration :: Ctx r s -> Int -> ST s ()
endIteration c k =
  readSTRef (ctxLogs c) >>= \case
    l : ls -> do
      let cfg = ctxConfig c
          (stale, kept)
            | cfgDiscardAll cfg = (l, [])
            | otherwise = partition (IS.member k . fst) l
      when (cfgDiscard cfg) (mapM_ snd stale)
      writeSTRef (ctxLogs c) $ case ls of
        o : os -> (kept ++ o) : os
        [] -> []
    [] -> pure ()

-- | Memoise a rule that does not take part in left recursion.
memo :: (r -> Table s a) -> String -> P r s a -> P r s a
memo sel rawName body = P $ \c i ->
  if not (cfgMemo (ctxConfig c))
    then (\(r, _, _, _) -> r) <$> evalBody c name i body
    else do
      let t = sel (ctxStore c)
      IM.lookup i <$> readSTRef t >>= \case
        Just e -> replay c e
        Nothing -> do
          (r, f, errs, d) <- evalBody c name i body
          modifySTRef' t (IM.insert i (Entry r f errs d))
          bumpEntries c name 1
          logUndo c d (modifySTRef' t (IM.delete i) >> bumpEntries c name (-1))
          pure r
  where
    name = T.pack rawName

-- | Memoise a rule with arguments. The arguments are part of the key.
memoArg :: Ord k => (r -> ArgTable s k a) -> String -> k -> P r s a -> P r s a
memoArg sel rawName k body = P $ \c i ->
  if not (cfgMemo (ctxConfig c))
    then (\(r, _, _, _) -> r) <$> evalBody c name i body
    else do
      let t = sel (ctxStore c)
      (IM.lookup i <$> readSTRef t) >>= \m -> case m >>= M.lookup k of
        Just e -> replay c e
        Nothing -> do
          (r, f, errs, d) <- evalBody c name i body
          modifySTRef' t (IM.insertWith M.union i (M.singleton k (Entry r f errs d)))
          bumpEntries c name 1
          logUndo c d (modifySTRef' t (IM.adjust (M.delete k) i) >> bumpEntries c name (-1))
          pure r
  where
    name = T.pack rawName

-- | A rule that is not memoised (@%nomemo@). Its body is evaluated on every
-- call. The failure record is kept per evaluation as for memoised rules, so
-- that turning memoisation off does not change the reported error.
nomemo :: String -> P r s a -> P r s a
nomemo rawName body = P $ \c i -> (\(r, _, _, _) -> r) <$> evalBody c name i body
  where
    name = T.pack rawName

-- | Evaluate a rule that takes part in left recursion.
--
-- On the first call at an offset the memo entry is seeded with a failure,
-- and the body is re-evaluated while each evaluation matches more input
-- than the previous one. The longest match is the result. Entries that
-- other rules wrote during an iteration may depend on the seed of that
-- iteration; those that read the seed are discarded at the end of every
-- iteration, and the others are kept (ADR 0024). 'cfgDiscard' and
-- 'cfgDiscardAll' change this for tests.
memoLR :: (r -> Table s a) -> String -> P r s a -> P r s a
memoLR sel rawName body = P $ \c i -> do
  let t = sel (ctxStore c)
  IM.lookup i <$> readSTRef t >>= \case
    Just e -> replay c e
    Nothing -> do
      saved <- readSTRef (ctxFail c)
      writeSTRef (ctxFail c) NoFailure
      savedDeps <- readSTRef (ctxDeps c)
      depth <- readSTRef (ctxDepth c)
      let k = depth + 1
          -- Whoever reads the seed depends on this loop.
          seed r errs = Entry r NoFailure errs (IS.singleton k)
      writeSTRef (ctxDepth c) k
      before <- saveErrors c
      modifySTRef' t (IM.insert i (seed Fail noErrors))
      bumpEntries c name 1
      -- Each iteration starts from the errors before the growth, so that
      -- only the errors of the iteration that is kept remain. The result
      -- depends on the seeds read by every iteration, the last one included,
      -- since that one decides where the growth stops.
      let grow lastRes lastEnd lastErrs deps = do
            countEval c name i
            restoreErrors c before
            writeSTRef (ctxDeps c) IS.empty
            modifySTRef' (ctxLogs c) ([] :)
            r <- unP body c i
            d <- IS.union deps <$> readSTRef (ctxDeps c)
            endIteration c k
            case r of
              Ok j x | j > lastEnd -> do
                errs <- newErrors c before
                modifySTRef' t (IM.insert i (seed (Ok j x) errs))
                grow r j errs d
              Throw {} -> pure (r, noErrors, d)
              _ -> pure (lastRes, lastErrs, d)
      (res, errs, d) <- grow Fail (-1) noErrors IS.empty
      let deps = IS.delete k d
      writeSTRef (ctxDepth c) depth
      writeSTRef (ctxDeps c) (IS.union savedDeps deps)
      restoreErrors c before
      case res of
        Ok {} -> appendSlice c errs
        _ -> pure ()
      f <- readSTRef (ctxFail c)
      writeSTRef (ctxFail c) (mergeFailure saved f)
      modifySTRef' t (IM.insert i (Entry res f errs deps))
      logUndo c deps (modifySTRef' t (IM.delete i) >> bumpEntries c name (-1))
      pure res
  where
    name = T.pack rawName

-- Syntax trees -----------------------------------------------------------------

-- In a grammar with @%syntax@, every parser returns its value together with
-- the children it contributes to the syntax tree.

-- | Record a rule invocation as a node.
node :: SyntaxKind -> P r s (a, [Child]) -> P r s (a, [Child])
node k p = P $ \c i ->
  unP p c i >>= \case
    Ok j (v, kids) -> pure (Ok j (v, [CNode k i j kids Nothing]))
    bad -> pure (failed bad)

-- | Record a rule invocation as a single token.
token :: SyntaxKind -> P r s (a, [Child]) -> P r s (a, [Child])
token k p = P $ \c i ->
  unP p c i >>= \case
    Ok j (v, _) -> pure (Ok j (v, [CToken k i j Nothing]))
    bad -> pure (failed bad)

-- | A parser that contributes nothing but text.
plain :: P r s a -> P r s (a, [Child])
plain = fmap (\x -> (x, []))

-- | Label the children of a bound expression. If it produced no children
-- but consumed text, the text becomes a labelled token.
label :: String -> P r s (a, [Child]) -> P r s (a, [Child])
label rawLabel p = P $ \c i ->
  unP p c i >>= \case
    Ok j (v, kids)
      | null kids && j > i -> pure (Ok j (v, [CToken textKind i j (Just l)]))
      | otherwise -> pure (Ok j (v, map (setLabel l) kids))
    bad -> pure (failed bad)
  where
    l = T.pack rawLabel

-- | Zero or more repetitions in syntax mode.
manyS :: P r s (a, [Child]) -> P r s ([a], [Child])
manyS = fmap (\xs -> (map fst xs, concatMap snd xs)) . many

-- | One or more repetitions in syntax mode.
many1S :: P r s (a, [Child]) -> P r s ([a], [Child])
many1S = fmap (\xs -> (map fst xs, concatMap snd xs)) . many1

-- | An optional match in syntax mode.
optionalS :: P r s (a, [Child]) -> P r s (Maybe a, [Child])
optionalS = fmap (maybe (Nothing, []) (\(v, k) -> (Just v, k))) . optional

-- | The consumed text in syntax mode. The children are kept.
captureS :: P r s (a, [Child]) -> P r s (Text, [Child])
captureS p = P $ \c i ->
  unP p c i >>= \case
    Ok j (_, kids) -> pure (Ok j (slice (ctxInput c) i j, kids))
    bad -> pure (failed bad)

-- | A label or kind name from a string literal of generated code.
labelText :: String -> Text
labelText = T.pack

-- | Mark a binding as used without evaluating it. In syntax mode a binding
-- may exist only to label children in the tree.
touch :: a -> P r s ()
touch _ = pure ()

-- Labelled failures (ADR 0021) ----------------------------------------------

-- | @e ^label@. If the parser fails, throw the label at the position where
-- it was tried. In recovery mode, a recovery parser for the label is run
-- from that position instead; if it succeeds, its value is the result and
-- a syntax error is recorded. A label thrown inside the recovery parser
-- makes the recovery fail.
labeled :: String -> Maybe (P r s a) -> P r s a -> P r s a
labeled = labeledWith (\_ _ v -> v)

-- | 'labeled' in syntax mode: the recovered range becomes an error node
-- whose children are those of the recovery rule.
labeledS :: String -> Maybe (P r s (a, [Child])) -> P r s (a, [Child]) -> P r s (a, [Child])
labeledS = labeledWith (\i j (v, kids) -> (v, [CNode errorKind i j (unwrap kids) Nothing]))
  where
    unwrap [CNode _ _ _ ks Nothing] = ks
    unwrap ks = ks

labeledWith :: (Int -> Int -> a -> a) -> String -> Maybe (P r s a) -> P r s a -> P r s a
labeledWith wrap rawLabel recovery p = P $ \c i -> do
  savedFail <- readSTRef (ctxFail c)
  writeSTRef (ctxFail c) NoFailure
  savedErrors <- saveErrors c
  r <- unP p c i
  local <- readSTRef (ctxFail c)
  writeSTRef (ctxFail c) (mergeFailure savedFail local)
  case r of
    Fail -> do
      restoreErrors c savedErrors
      case recovery of
        Just q | cfgRecover (ctxConfig c) ->
          unP q c i >>= \case
            Ok j v -> do
              let expected = case local of
                    Failure _ xs -> xs
                    NoFailure -> S.empty
              modifySTRef' (ctxErrors c) (\(ErrLog n xs) -> ErrLog (n + 1) (SyntaxError (Just l) (i, j) (posAt c i) expected : xs))
              pure (Ok j (wrap i j v))
            _ -> restoreErrors c savedErrors >> pure (Throw i l)
        _ -> pure (Throw i l)
    _ -> pure r
  where
    l = T.pack rawLabel

-- | Discard the value of a recovery parser, for a label on an expression
-- without a value.
voidP :: P r s a -> P r s ()
voidP = fmap (const ())

-- | 'voidP' in syntax mode.
voidS :: P r s (a, [Child]) -> P r s ((), [Child])
voidS = fmap (\(_, kids) -> ((), kids))
